public class Counter {
    private int count;

    public void increment() {
        count++;
    }

    public int sum(int a, int b) {
        int total = a + b;
        return total * 2;
    }

    public static void main(String[] args) {
        Counter c = new Counter();
        c.increment();
        System.out.println(c.sum(3, 4) + c.count);
    }
}

