public class LazyInit {
    static class Lazy {
        static { System.out.println("Lazy initialized"); }
        static final int CONST = 7;      // compile-time constant, inlined by javac
        static int value = 42;
    }

    public static void main(String[] args) {
        System.out.println("Constant: " + Lazy.CONST);
        System.out.println("Before value");
        System.out.println("Value: " + Lazy.value);
    }
}

