public class Trace {
    static int parse(String s) {
        return Integer.parseInt(s);
    }

    static int total(String[] items) {
        int sum = 0;
        for (String s : items) {
            sum += parse(s);
        }
        return sum;
    }

    public static void main(String[] args) {
        System.out.println(total(new String[] {"1", "2", "x3"}));
    }
}

